def cachedmethod(cache, key=keys.methodkey, lock=None, condition=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """

    def decorator(method):
        if condition is not None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                cd = condition(self) if callable(condition) else condition
                with cd:
                    try:
                        return c[k]
                    except KeyError:
                        pass
                    if not hasattr(c, '_in_progress'):
                        c._in_progress = set()
                    if k in c._in_progress:
                        cd.wait()
                        try:
                            return c[k]
                        except KeyError:
                            pass
                    c._in_progress.add(k)
                v = method(self, *args, **kwargs)
                with cd:
                    try:
                        c[k] = v
                    except ValueError:
                        c._in_progress.discard(k)
                        cd.notify_all()
                        return v
                    c._in_progress.discard(k)
                    cd.notify_all()
                    return v

            def clear(self):
                c = cache(self)
                if c is not None:
                    cd = condition(self) if callable(condition) else condition
                    with cd:
                        c.clear()
                        if hasattr(c, '_in_progress'):
                            c._in_progress.clear()

        elif lock is None:

            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v

            def clear(self):
                c = cache(self)
                if c is not None:
                    c.clear()

        else:

            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                # in case of a race, prefer the item already in the cache
                try:
                    with lock(self):
