def _cached_condition_info(func, cache, key, cond, info):
    """Wrapper using threading.Condition for stampede protection."""
    h = m = 0
    ip = set()

    def wrapper(*args, **kwargs):
        nonlocal h, m
        k = key(*args, **kwargs)
        with cond:
            try:
                v = cache[k]
                h += 1
                return v
            except KeyError:
                pass
            if k in ip:
                cond.wait()
                try:
                    v = cache[k]
                    h += 1
                    return v
                except KeyError:
                    pass
            m += 1
            ip.add(k)
        v = func(*args, **kwargs)
        with cond:
            try:
                cache[k] = v
            except ValueError:
                ip.discard(k)
                cond.notify_all()
                return v
            ip.discard(k)
            cond.notify_all()
            return v

    def cache_clear():
        nonlocal h, m
        with cond:
            cache.clear()
            ip.clear()
            h = m = 0

    def cache_info():
        with cond:
            return info(h, m)

    wrapper.cache_clear = cache_clear
    wrapper.cache_info = cache_info
    return wrapper
